const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/coordination_issues/%7Bcoordination_issue_id%7D/procore_item_associations',
  headers: {'content-type': 'application/json'},
  body: {project_id: 12345, procore_item: {item_id: 1, item_type: 'rfi'}},
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/coordination_issues/%7Bcoordination_issue_id%7D/procore_item_associations"),
    Content = new StringContent("{\"project_id\":12345,\"procore_item\":{\"item_id\":1,\"item_type\":\"rfi\"}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

